#include "../host/file_assets.hpp"
#include "../app/actor_animation.hpp"
#include <chrono>
#include <iostream>
#include <fstream>
#include <zlib.h>
int main(int argc,char**argv){try{
 if(argc!=3)throw std::runtime_error("ASSETROOT NEW_JSON");if(std::filesystem::exists(argv[2]))throw std::runtime_error("Output exists");hades::FileAssets assets(argv[1]);hades::ActorAnimationBank bank;bank.load(assets);auto run=bank.find("ZagreusRun");if(!run)throw std::runtime_error("Run missing");constexpr float tau=6.283185307179586f;for(uint32_t a=0;a<4;++a)if(bank.selectedAngleForFacing(*run,float(a)*tau/4)!=a*2)throw std::runtime_error("Source cardinal facing");uint64_t samples=0,bytes=0;auto start=std::chrono::steady_clock::now();
 for(size_t c=0;c<bank.clips().size();++c){const auto& clip=bank.clips()[c];for(size_t s=0;s<clip.slides.size();++s)for(uint32_t a=0;a<clip.originalAngleIndices.size();++a){auto image=bank.sample(c,s,a);if(image.rgba.size()!=size_t(image.width)*image.height*4)throw std::runtime_error("Frame size");auto rect=image.worldRect(clip);if(rect[2]<=0||rect[3]<=0)throw std::runtime_error("Geometry size");++samples;bytes+=image.rgba.size();if(bank.stats().cachedBytes>bank.CacheBytes||bank.stats().cachedFrames>bank.CacheFrames)throw std::runtime_error("Cache bound");}}
 hades::ActorAnimationPlayback play;size_t events=0;play.play(bank,"ZagreusSwordAttack1",[&](auto&,auto&){++events;});if(play.originalFrame()!=17||play.animationBlocksAttack()!=false)throw std::runtime_error("Native start/default flag");play.advance(1.f/60);if(play.originalFrame()!=18)throw std::runtime_error("Source second slide");play.advance(.5);if(play.originalFrame()!=19)throw std::runtime_error("Native one-step cap");
 play.play(bank,"ZagreusSwordCharge1");for(int i=0;i<8;++i)play.advance(1.f/60);if(play.finished())throw std::runtime_error("Source charge early finish");play.advance(1.f/60);if(!play.finished())throw std::runtime_error("Source charge completion");play.play(bank,"ZagreusRun");play.advance(1.f/60);if(play.originalFrame()!=2)throw std::runtime_error("Native book60fps");play.advance(.25);if(play.originalFrame()<16||play.originalFrame()>17)throw std::runtime_error("Book fractional progression");play.reset();if(play.animationBlocksAttack())throw std::runtime_error("No animation flag must remain unknown");
 const auto& st=bank.stats();const auto elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::ofstream out(argv[2]);out<<"{\"schema\":\"hades-actor-animation-validation-v1\",\"clips\":"<<bank.clips().size()<<",\"samples\":"<<samples<<",\"raw_bytes_sampled\":"<<bytes<<",\"elapsed_seconds\":"<<elapsed<<",\"cache_frames\":"<<st.cachedFrames<<",\"cache_bytes\":"<<st.cachedBytes<<",\"misses\":"<<st.misses<<",\"hits\":"<<st.hits<<",\"inflated_bytes\":"<<st.inflateBytes<<",\"inflate_ms\":"<<st.inflateMilliseconds<<",\"native_slide_assertions\":true}\n";std::cout<<"PASS clips="<<bank.clips().size()<<" samples="<<samples<<" cache="<<st.cachedBytes<<" inflate_ms="<<st.inflateMilliseconds<<'\n';
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
